import type { Linked } from "psyche";

import { posts } from "../posts";
import type { Page } from "../search";

// the search index, generated by the site: psyche only searches it. each
// record is linked to its page
export const GET = () =>
  Response.json([
    {
      href: "/",
      value: {
        title: "A winter garden",
        body: "Planting through the cold months.",
        section: "Pages",
      },
    },
    ...posts.map((post): Linked<Page> => ({
      href: `/posts/${post.slug}/`,
      value: {
        title: post.title,
        body: post.sections.map((section) => `${section.heading}\n${section.text}`).join("\n"),
        authors: post.authors,
        categories: post.categories,
        headings: post.sections.map(({ id, heading }) => ({ value: heading, href: `#${id}` })),
        section: "Posts",
      },
    })),
  ] satisfies Linked<Page>[]);
